'use strict';
const F=Farm,$=id=>document.getElementById(id),KEY='lang-may-v1';let s,loadWarning='',tool='seed',seed='carrot',toastTimer,walkTimer,modalView='',questTab='journey',profileGender='female',pendingImport=null,pendingCards=null,tickSignature='',plotPage=0,fishAlerts=new Set(),pondTab='rod',selectedBait='basic';
try{const raw=localStorage.getItem(KEY);s=raw?F.migrate(JSON.parse(raw)):F.initial()}catch(e){s=F.initial();loadWarning='Không đọc được tiến độ cũ. Chưa ghi đè bản cũ; bạn có thể khôi phục từ tệp sao lưu.'}F.refreshDaily(s);
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=n=>{n=Math.max(0,Math.ceil(n));return n>=60?`${Math.floor(n/60)}p ${n%60}s`:`${n}s`};
const cropAtlas={grape:[0,0],blueberry:[50,0],watermelon:[100,0],pineapple:[0,100],sunflower:[50,100],cotton:[100,100]};
const foodKeys=Object.keys(F.dishes);
// Hand-drawn UI icons (public/icons/*.svg) for actions that have no produce picture.
// Growing-plant pictures (public/crops/*.svg) for crops whose produce is only an emoji; used wherever a crop is shown as a plant.
const PREMIUM_ART={grapeGreen:'goods/grapeGreen-v68.png',blueberrySweet:'goods/blueberrySweet-v68.png',goldenMelon:'goods/goldenMelon-v68.png',pineappleHoney:'goods/pineappleHoney-v68.png'};
const PLANT_ART=new Set(['herbs','lettuce','cucumber','greenbean','sweetpotato','lotus','chili','coconut','gac','coffee']);
const cropImage=(key,cls='item-art')=>PLANT_ART.has(key)?`<img class="${cls} plant-art" src="crops/${key}.svg?v=1.2" alt="${F.goods[key].name}">`:cropAtlas[key]?atlasPlant(key,cls):image(key,cls);
const icon=(name,cls='item-art')=>`<img class="${cls}" src="icons/${name}.svg" alt="">`;
// Harvest products drawn for crops that had no product picture (public/goods/*.svg): bag, orders, harvest pop-up.
const GOODS_ART=new Set(['wool','pork','herbs','lettuce','cucumber','greenbean','sweetpotato','lotus','chili','coconut','gac','coffee','grape','blueberry','watermelon','pineapple','sunflower','cotton']);
const goodsArtSrc=key=>PREMIUM_ART[key]|| (GOODS_ART.has(key)?'goods/'+key+'.svg?v=1.0':!F.goods[key]?.food&&!F.goods[key]?.icon?(F.goods[key]?.art||key)+'.png':'');
window.goodsArtSrc=goodsArtSrc;
const atlasPlant=(key,cls)=>`<span class="${cls} atlas-crop" style="background-position:${cropAtlas[key][0]}% ${cropAtlas[key][1]}%" role="img" aria-label="${F.goods[key].name}"></span>`;
const image=(key,cls='item-art')=>PREMIUM_ART[key]?`<img class="${cls} goods-art" src="${PREMIUM_ART[key]}" alt="${F.goods[key].name}" decoding="async">`:GOODS_ART.has(key)?`<img class="${cls} goods-art" src="${goodsArtSrc(key)}" alt="${F.goods[key].name}">`:F.goods[key]?.food?`<span class="${cls} food-sprite" style="background-position:${(foodKeys.indexOf(key)%4)*100/3}% ${Math.floor(foodKeys.indexOf(key)/4)*50}%" role="img" aria-label="${F.goods[key].name}"></span>`:cropAtlas[key]?`<span class="${cls} atlas-crop" style="background-position:${cropAtlas[key][0]}% ${cropAtlas[key][1]}%" role="img" aria-label="${F.goods[key].name}"></span>`:F.goods[key]?.icon?`<span class="${cls} product-icon">${F.goods[key].icon}</span>`:`<img class="${cls}" src="${F.goods[key]?.art||key}.png" alt="">`;

function captureLeisureView(root){const scroller=root.querySelector?.('.leisure-scene');if(!scroller)return null;const hand=scroller.querySelector('.card-hand'),anchor=scroller.querySelector('.your-hand'),r=scroller.getBoundingClientRect(),ar=anchor?.getBoundingClientRect(),focused=document.activeElement,focus=scroller.contains(focused)&&['BUTTON','INPUT','SELECT'].includes(focused.tagName)?{id:focused.id,action:focused.dataset?.action,room:focused.dataset?.room,key:focused.dataset?.key,card:focused.dataset?.card,value:['INPUT','SELECT'].includes(focused.tagName)?focused.value:undefined,start:focused.selectionStart,end:focused.selectionEnd}:null;return {top:scroller.scrollTop,left:scroller.scrollLeft,handLeft:hand?.scrollLeft||0,anchorOffset:ar&&ar.top>=r.top&&ar.top<r.bottom?ar.top-r.top:null,focus,details:[...scroller.querySelectorAll('details')].map(x=>x.open)};}
function restoreLeisureView(root,view){if(!view)return;const scroller=root.querySelector?.('.leisure-scene');if(!scroller)return;scroller.querySelectorAll('details').forEach((x,i)=>x.open=!!view.details[i]);scroller.scrollTop=view.top;scroller.scrollLeft=view.left;const hand=scroller.querySelector('.card-hand');if(hand)hand.scrollLeft=view.handLeft;const anchor=scroller.querySelector('.your-hand');if(view.anchorOffset!==null&&anchor)scroller.scrollTop+=anchor.getBoundingClientRect().top-scroller.getBoundingClientRect().top-view.anchorOffset;if(view.focus){const f=view.focus,el=[...scroller.querySelectorAll('button,input,select')].find(x=>f.id?x.id===f.id:x.dataset.action===f.action&&x.dataset.room===f.room&&x.dataset.key===f.key&&x.dataset.card===f.card);if(el){if(f.value!==undefined)el.value=f.value;el.focus?.({preventScroll:true});if(f.start!==null&&f.start!==undefined&&el.setSelectionRange)try{el.setSelectionRange(f.start,f.end)}catch{}}}}
function html(id,value){const node=$(id);if(node.innerHTML===value)return;const view=id==='scene'&&s.zone==='leisure'?captureLeisureView(node):null;const cafeScroll=id==='scene'&&s.zone==='cafe'?node.querySelector?.('.cafe-shop')?.scrollTop:null;const cafeTicketsLeft=id==='scene'&&s.zone==='cafe'?node.querySelector?.('.cafe-tickets')?.scrollLeft:null;node.innerHTML=value;if(view)restoreLeisureView(node,view);if(cafeScroll!==undefined&&cafeScroll!==null){const panel=node.querySelector?.('.cafe-shop');if(panel)panel.scrollTop=cafeScroll}if(cafeTicketsLeft!==undefined&&cafeTicketsLeft!==null){const tickets=node.querySelector?.('.cafe-tickets');if(tickets)tickets.scrollLeft=cafeTicketsLeft}}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3600)}
function save(){if(loadWarning){$('saveState').textContent='Bản lưu lỗi: mở Cài đặt để xử lý';return}try{localStorage.setItem(KEY,JSON.stringify(s));if(!window.farmSync)$('saveState').textContent='Đã lưu trên máy';window.farmSync?.queue()}catch{window.farmSync?.queue();if(!window.farmSync)$('saveState').textContent='Chưa lưu được · Hãy tải bản sao lưu';toast('Trình duyệt không cho lưu tiến độ. Hãy tải bản sao lưu trong Cài đặt.')}}
function progress(m,d=false){return Math.min((d?s.daily.stats:s.stats)[m.key],m.target)}
function claimable(){return F.missions.filter(m=>!s.claimed.includes(m.id)&&progress(m)>=m.target).length+F.dailyFor(s).filter(m=>!s.daily.claimed.includes(m.id)&&progress(m,true)>=m.target).length+F.weeklyMissions(s).filter(m=>!s.weekly.claimed.includes(m.id)&&m.tasks.every(t=>t.progress>=t.target)).length+(!s.daily.gift?1:0)}
function action(a){if(window.farmSync?.blocked)return false;const prev=JSON.parse(JSON.stringify(s));try{const result=F.perform(s,a);if(!['profile','travel','equipOutfit'].includes(a.type))window.farmAnalytics?.played();window.farmAudio?.onAction(a,result);save();render();feedback(a,result,prev);if(modalView&&!['profile','unlock'].includes(modalView))showModal(modalView);toast(result.message+(result.levelUp?` ⭐ Lên cấp ${result.levelUp}!`:''));return true}catch(e){s=prev;window.farmAudio?.effect('error');toast(e.message);return false}}
// Crop growth: seed (not yet watered) -> young sprout (first 40% of the grow time) -> growing plant -> ripe.
const CROP_STAGES=[['seed','Hạt giống','Hạt'],['sprout','Cây non','Cây non'],['young','Cây đang lớn','Đang lớn'],['ready','Cây chín','Chín']],SPROUT_SHARE=.4;
function cropStage(p,now=Date.now()){if(!p)return null;const T=F.crops[p.crop].time*1000,end=p.start+T,pct=Math.max(0,Math.min(1,(now-p.start)/T));let key,nextAt=null;if(!p.water)key='seed';else if(F.ready(p))key='ready';else if(pct<SPROUT_SHARE){key='sprout';nextAt=p.start+T*SPROUT_SHARE}else{key='young';nextAt=end}const idx=CROP_STAGES.findIndex(x=>x[0]===key),[,full,short]=CROP_STAGES[idx],name=F.crops[p.crop].name;const title=name+' · '+full+' ('+(idx+1)+'/4)'+(key==='seed'?' · tưới nước để cây bắt đầu lớn':key==='ready'?' · thu hoạch được rồi':p.pest?' · có sâu, bắt sâu để cây lớn tiếp':' · '+(key==='sprout'?'lớn tiếp sau '+clock((nextAt-now)/1000)+' · chín sau '+clock((end-now)/1000):'chín sau '+clock((end-now)/1000)));return {key,idx,full,short,nextAt,end,pct,title}}
// Animals with measured legs (critter-joints.js) are drawn as SVG: the painted picture's body plus one piece per leg,
// which avatar-world.js steps every frame. The pig (the herd kept under the 'buffalo' key) has no painting yet and is
// drawn by avatar-rig.js. Without either, the plain picture is used.
function critterArt(src,cls,alt,style,fallback,mood){if(window.AvatarRig?.speciesOf(src)==='pig')return AvatarRig.animal('pig',{cls,label:alt,style,mood});const d=window.XOM_CRITTERS?.[src.split('?')[0]];if(!d)return fallback;const img=(c,clip,origin)=>'<image class="'+c+'" href="'+src+'" width="'+d.w+'" height="'+d.h+'" style="'+(clip?'clip-path:'+clip+';':'')+(origin?'transform-origin:'+origin:'')+'"/>';const body=img('cr-body',d.body,d.pivot?d.pivot[0]+'px '+d.pivot[1]+'px':''),legs=(d.legs||[]).map(l=>img('cr-leg cr-leg-'+l.g,l.clip,l.ox+'px '+l.oy+'px')).join('');return '<svg'+(cls?' class="'+cls+'"':'')+' data-critter="'+d.type+'" viewBox="0 0 '+d.w+' '+d.h+'" role="img" aria-label="'+alt+'"'+(style?' style="'+style+'"':'')+(d.peck?' data-peck="'+d.peck+'"':'')+(mood?' data-mood="'+mood+'"':'')+'><g class="cr-rig" style="transform-origin:'+d.w/2+'px '+d.h+'px">'+body+legs+'</g></svg>'}
function countdown(t){return `<span data-countdown="${t}">${clock((t-Date.now())/1000)}</span>`}
function animalText(k){const a=s.animals[k],d=F.animals[k];return !a.owned?'Chưa có vật nuôi':!a.readyAt?'Đang đói, chờ bạn cho ăn':a.readyAt<=Date.now()?`${F.animalYield(s,k)} ${F.goods[d.product].name} đã sẵn sàng`:'Còn '+countdown(a.readyAt)}
function animalButton(k){const a=s.animals[k],d=F.animals[k];if(!a.owned)return `<button class="primary" data-action="buyAnimal" data-key="${k}" ${F.level(s)<d.level?'disabled':''}>${F.level(s)<d.level?'Cấp '+d.level:d.buy+' xu · Mua'}</button>`;return `<button class="primary" data-action="animal" data-key="${k}" ${a.readyAt>Date.now()?'disabled':''}>${!a.readyAt?'Cho cả đàn ăn · '+d.feed*a.count+' xu':a.readyAt<=Date.now()?'Nhận sản phẩm':'Đang nghỉ…'}</button>`}
function levelGuide(){const l=F.level(s),m=F.specialMission(s),xp=Math.max(0,F.threshold(Math.min(F.MAX_LEVEL,l+1))-s.xp);return `<button class="level-guide" data-action="levelGoal"><strong>${l===F.MAX_LEVEL?'Đã đạt cấp 200':'Mục tiêu cấp '+(l+1)}</strong><span>${l===F.MAX_LEVEL?'Tiếp tục nhiệm vụ và trang trí':xp.toLocaleString('vi-VN')+' XP còn thiếu'+(m?' · '+m.tasks.filter(t=>t.progress<t.target).length+' mục tiêu đặc biệt':' · Nhiệm vụ hôm nay có thưởng XP')}</span></button>`}
// Field pages (more than 48 plots): the switcher sits on the edge of the bottom bar, where it never covers the plots or
// scrolls away with the scene on phones. The copy inside the scene is kept for the markup but hidden by CSS.
function syncFieldPager(){const bar=document.querySelector?.('.play-bottom');if(!bar)return;let nav=document.getElementById('fieldPager');const n=s.zone==='farm'&&s.plots.length>48?Math.ceil(s.plots.length/48):0;
if(!n){if(nav)nav.hidden=true;return}
if(!nav){nav=document.createElement('nav');nav.id='fieldPager';nav.className='field-pager';nav.setAttribute('aria-label','Chọn cánh đồng');bar.appendChild(nav)}
const markup=Array.from({length:n},(_,i)=>`<button data-action="plotPage" data-key="${i}" class="${i===plotPage?'active':''}" ${i===plotPage?'aria-current="page"':''}>Cánh đồng ${i+1}</button>`).join('');
if(nav.innerHTML!==markup)nav.innerHTML=markup;nav.hidden=false}
function farmScene(){plotPage=Math.max(0,Math.min(plotPage,Math.floor((s.plots.length-1)/48)));const visible=s.plots.slice(plotPage*48,(plotPage+1)*48);const field=`<div class="plots plots-progressive" style="--plot-cols:${visible.length<=16?4:visible.length<=36?6:8};--plot-rows:${Math.ceil(visible.length/(visible.length<=16?4:visible.length<=36?6:8))}" id="plots" aria-label="Vườn ${s.plots.length} ô đất">`+visible.map((p,local)=>{const i=plotPage*48+local;const st=cropStage(p),state=!st?'':st.key==='seed'||st.key==='sprout'?'small':st.key==='ready'?'':'growing';return `<button class="plot ${p?'':'empty'} ${p?.water?'watered':''} ${F.ready(p)?'ready':''} ${st?'stage-'+st.key:''}" data-action="plot" data-index="${i}" ${st?'data-stage="'+st.key+'" title="'+esc(st.title)+'"':''} aria-label="Ô ${i+1}: ${st?esc(st.title):'đất trống'}">${p?`<span class="plant-wrap">${cropImage(state==='small'?'sprout':p.crop,'crop-img '+state+' stage-'+st.key)}</span><span class="status">${!p.water?'💧':p.pest?'🐛':F.ready(p)?'✨':''}</span><small>${F.ready(p)?'Thu hoạch':!p.water?'Cần tưới':p.pest?'Có sâu':'<span class="stage-name">'+st.short+' </span>'+countdown(st.nextAt)}</small>${p.water&&st.key!=='ready'?`<span class="grow-bar" data-from="${p.start}" data-to="${st.end}" style="--grow:${Math.round(st.pct*100)}%" aria-hidden="true"></span>`:''}`:''}</button>`}).join('')+`</div>`;const companions=Object.entries(F.pets).filter(([k])=>s.pets[k]).map(([k,d],i)=>`<div class="farm-pet pet-${k}" style="--pet-x:${[27,41,56,70][i]}%;--pet-y:${[93,96,93,96][i]}%;--pet-x-m:${[15,37,59,80][i]}%;--pet-y-m:${[86,90,86,90][i]}%;--pet-delay:${i*.65}s">${critterArt('pets/'+d.art+'.png?v=47.2','critter',d.name+' đang đi dạo','','<img src="pets/'+d.art+'.png?v=47.2" alt="'+d.name+' đang đi dạo" draggable="false">')}<span>${d.name}</span></div>`).join('');const pages=s.plots.length>48?`<nav class="field-pages" aria-label="Chọn cánh đồng">${Array.from({length:Math.ceil(s.plots.length/48)},(_,i)=>`<button data-action="plotPage" data-key="${i}" ${i===plotPage?'disabled':''}>Cánh đồng ${i+1}</button>`).join('')}</nav>`:'';return levelGuide()+pages+field+companions+(s.reservedCrops.length?`<div class="reserved-note">Còn ${s.reservedCrops.length} cây từ ruộng cũ. Cây sẽ chuyển vào ô trống sau khi thu hoạch.</div>`:'')}
function petShopScene(){return `<section class="pet-shop"><header class="pet-shop-heading"><span>🐾</span><div><h2>Khu thú cưng</h2><p>Chọn một người bạn đồng hành. Thú đã mua sẽ thong thả đi dạo trong nông trại.</p></div><strong>CẤP 100</strong></header><div class="pet-shop-grid">${Object.entries(F.pets).map(([k,d])=>`<article class="pet-card ${s.pets[k]?'pet-owned':''}"><span class="pet-art" data-c3d="animal:${PET_3D[d.art]||''}"><img src="pets/${d.art}.png?v=47.2" alt="${d.name}" loading="lazy"></span><div><h3>${d.name}</h3><p>${s.pets[k]?'Đang sống vui vẻ trong nông trại':'Bạn đồng hành đáng yêu'}</p><strong>${d.cost.toLocaleString('vi-VN')} xu</strong></div><button class="primary" data-action="buyPet" data-key="${k}" ${s.pets[k]||s.coins<d.cost?'disabled':''}>${s.pets[k]?'Đã mua':'Mua thú cưng'}</button></article>`).join('')}</div><p class="pet-shop-note">Thú cưng được lưu cùng tiến độ của bạn. Mỗi loài chỉ cần mua một lần.</p></section>`}
const penNames={chicken:'Chuồng gà',cow:'Chuồng bò',sheep:'Chuồng cừu',duck:'Chuồng vịt',goat:'Chuồng dê',buffalo:'Chuồng heo'};
// Herd mood shows in the pen: hungry animals look thin, fed ones turn round and content. avatar-world.js picks a
// random animal now and then to say one of these lines in a speech bubble.
function penMood(k){const v=s.animals[k];return !v.owned?'empty':!v.readyAt?'hungry':v.readyAt<=Date.now()?'ready':'fed'}
const HERD_SOUND={chicken:'Cục tác!',duck:'Cạp cạp!',cow:'Ummm…',sheep:'Be be~',goat:'Be he he~',buffalo:'Ụt ịt!'};
function herdTips(k,mood){const sound=HERD_SOUND[k]||'',prod=F.animals[k].product,art=image(prod,'tip-art');return mood==='hungry'?['🌾 Đói quá!','Cho ăn đi!','Đói bụng…',sound+' Đói!']:mood==='fed'?['♥ No căng','💤 Zzz…','♪ Vui ghê',sound]:mood==='ready'?[art+'Thu hoạch!',art+'Có '+F.goods[prod].name.toLowerCase()+'!',art+sound]:[]}
function penArt(k,cls='pen-building-art'){const v=s.animals[k],total=v.owned?v.count:0,count=Math.min(total,20),cols=count<=4?2:count<=9?3:count<=16?4:5,mood=penMood(k);return `<span class="paddock ${cls}" data-c3d="pen:${k}"><img class="paddock-base" src="pens/${k}-pen.png?v=2.0" alt="${penNames[k]} riêng có hàng rào và mái che"><span class="herd" style="--herd-cols:${cols}" data-mood="${mood}" data-tips="${esc(herdTips(k,mood).join('|'))}">${Array.from({length:count},(_,i)=>`<span class="herd-slot">${critterArt('pens/'+k+'-animal.png?v=47.2','herd-animal',F.animals[k].name+' '+(i+1),'--animal-delay:'+(i*.23)+'s','<img class="herd-animal" src="pens/'+k+'-animal.png" alt="'+F.animals[k].name+' '+(i+1)+'" style="--animal-delay:'+(i*.23)+'s">',mood)}</span>`).join('')}</span><img class="paddock-front front-${k}" src="pens/${k}-pen.png?v=2.0" alt="" aria-hidden="true">${total>count?'<span class="herd-more">+'+(total-count)+' con</span>':''}</span>`}
function barnScene(){return `<div class="barn-yard"><div class="yard-heading"><div><h2>Chuồng trại</h2><p>Mỗi đàn có chuồng riêng · Chạm vào chuồng để chăm sóc</p></div><button data-action="automation">Tự động chăn nuôi</button></div><div class="paddock-grid">${Object.entries(F.animals).map(([k,d])=>`<button class="paddock-button pen-${penMood(k)} real-pen ${s.animals[k].owned?'':'paddock-empty'}" data-action="pen" data-key="${k}" aria-label="Vào ${penNames[k]}"><strong>${penNames[k]}</strong>${penArt(k)}<span class="pen-info"><span class="herd-status">${s.animals[k].owned?s.animals[k].count+' / '+F.penCapacity(s,k)+' con · Chuồng '+s.animals[k].penLevel:'Mua vật nuôi · Cấp '+d.level}</span><small>${s.animals[k].owned?(!s.animals[k].readyAt?'Đang đói · Cho ăn':s.animals[k].readyAt<=Date.now()?'Đã no · Sản phẩm sẵn sàng':'Đã no · Đang nghỉ · '+countdown(s.animals[k].readyAt)):'Chuồng đang trống'}</small></span></button>`).join('')}</div></div>`}

function penDialog(k){const d=F.animals[k],v=s.animals[k],u=F.penUpgrades[v.penLevel],capacity=F.penCapacity(s,k);modal(penNames[k],`<div class="pen-detail">${penArt(k,'pen-portrait')}<div><h3>${d.name} · ${v.count}/${capacity} con</h3><p>${animalText(k)}</p>${animalButton(k)}<p>Mỗi lượt cả đàn nhận <b>${v.owned?F.animalYield(s,k):d.amount} ${F.goods[d.product].name}</b> sau ${clock(d.time)}.</p>${v.owned?`<button data-action="addAnimal" data-key="${k}" ${v.readyAt||v.count>=capacity||s.coins<(d.buy||100)?'disabled':''}>Mua thêm con · ${d.buy||100} xu</button><small>Nhận sản phẩm đang có trước khi thêm con.</small>`:''}</div></div>${v.owned?`<section class="pen-upgrade"><h3>Chuồng cấp ${v.penLevel}${v.penLevel<=5?' / 5':''} · ${capacity} chỗ</h3><p>${u?'Nâng thêm 4 chỗ và tăng sản phẩm cho mỗi con.':'Đã mở tối đa '+capacity+' con cho chuồng này.'}</p>${u?`<button class="primary" data-action="upgradePen" data-key="${k}" ${s.coins<u.cost||F.level(s)<u.level||v.readyAt?'disabled':''}>Nâng chuồng · ${u.cost} xu</button><small>Cần nhân vật cấp ${u.level}.</small>`:''}</section>`:''}<button class="text-link full" data-action="bag">Bán sản phẩm</button>`,'pen:'+k)}
function workDialog(){const current=s.work.active;modal('Việc làm kiếm xu',`<p class="modal-note">Không tốn vốn, không lấy nguyên liệu trong kho. Làm một việc mỗi lần; trong lúc chờ bạn vẫn chăm vườn được. Nhận tiền xong có thể làm tiếp.</p>${current?`<section class="active-work"><strong>${F.workTasks[current.key].name}</strong><p>${current.readyAt<=Date.now()?'Đã xong! Nhận tiền công nhé.':'Đang làm · '+countdown(current.readyAt)}</p><button class="primary" data-action="collectWork" ${current.readyAt>Date.now()?'disabled':''}>Nhận ${F.income(s,F.workTasks[current.key].coins)} xu</button></section>`:''}<p class="work-total">Đã hoàn thành ${s.work.completed} việc</p><div class="work-grid">${Object.entries(F.workTasks).map(([k,t])=>`<article class="work-card"><h3>${t.name}</h3><p>${t.desc}</p><strong>+${F.income(s,t.coins)} xu · +${Math.floor(t.xp*(F.level(s)>=70?.9:1))} XP</strong><small>${clock(t.time)} · Cấp ${t.level}</small><button class="primary" data-action="startWork" data-key="${k}" ${current||F.level(s)<t.level?'disabled':''}>${F.level(s)<t.level?'Mở ở cấp '+t.level:'Nhận việc'}</button></article>`).join('')}</div>`,'work')}

function pondScene(){const ready=s.pond.nets.filter(n=>n&&n.readyAt<=Date.now()).length,bait=F.fishingBaits[selectedBait],amount=F.fishingYield(s,selectedBait),profit=amount*F.sellPrice(s,'fish')-bait.cost;return `<section class="lake-hub"><header class="lake-heading"><div><h2>Hồ Làng Mây</h2><span>Ao cấp ${s.pond.level}/8 · ${s.fishing.length}/8 chỗ câu</span></div><button data-action="pondUpgrade">Nâng ao</button></header><nav class="lake-tabs"><button class="${pondTab==='rod'?'chosen':''}" data-action="pondTab" data-key="rod">Câu cá</button><button class="${pondTab==='net'?'chosen':''}" data-action="pondTab" data-key="net">Thả lưới ${ready?'· '+ready+' lưới đầy':''}</button></nav><div class="lake-play ${s.fishing.some(Boolean)?'is-fishing':''}"><img class="lake-background" src="pond/lake-v44-hd.webp" alt="Bờ hồ và cầu gỗ"><span class="lake-fisher" data-c3d="${c3dChar(s.profile.gender,s.wardrobe.equipped,s.footwear.equipped,'fish')}"><img src="pens/fishing-${s.profile.gender}.png" alt="Nhân vật ngồi câu cá"></span>${pondTab==='rod'?lakeLines()+s.fishing.map((t,i)=>{const key=F.fishingBait(s,i),n=F.fishingYield(s,key),biting=t&&t<=Date.now();return `<button class="lake-bobber ${biting?'biting':t?'waiting':'empty'} ${justCast===i?'just-cast':''}" style="${lakeSpot(i)}" data-action="fish" data-index="${i}" aria-label="Chỗ ${i+1}: ${biting?'cá cắn câu, kéo cần':t?'đang chờ':'quăng cần'}">${t?'<span class="float" aria-hidden="true"><i></i></span><span class="ripple" aria-hidden="true"></span>':''}<span class="bobber-number">${i+1}</span><span class="bobber-state">${biting?'Cá cắn! Kéo':t?countdown(t):'Quăng cần'}</span></button>`}).join(''):s.pond.nets.map((n,i)=>{const full=n&&n.readyAt<=Date.now();return `<button class="lake-net-point ${n?'has-net':'empty'} ${full?'biting':''} ${justNet===i?'just-cast':''}" style="${netSpot4(i)}" data-action="netSpot" data-index="${i}" aria-label="Lưới ${i+1}: ${!n?'chọn lưới để thả':full?'lưới đầy, kéo lưới':'đang chờ'}">${n?`<span class="net-vis" aria-hidden="true">${NET_SVG}${full?`<span class="net-catch-peek">${Array.from({length:4},(_,j)=>`<span style="--j:${j}">${image(n.kind)}</span>`).join('')}</span>`:''}</span>`:''}<strong>Lưới ${i+1}</strong><span>${!n?'Thả lưới':full?'Đã đầy · Kéo':countdown(n.readyAt)}</span></button>`}).join('')}</div>${pondTab==='rod'?`<div class="bait-picker" aria-label="Chọn mồi câu">${Object.entries(F.fishingBaits).map(([key,b])=>`<button class="${selectedBait===key?'chosen':''}" data-action="chooseBait" data-key="${key}" aria-pressed="${selectedBait===key}"><strong>${b.name}</strong><span>${b.cost} xu · ${b.time/60} phút</span><small>${F.fishingYield(s,key)} cá / lượt</small></button>`).join('')}</div><p class="lake-summary">${bait.name}: nhận <b>${amount} cá</b> · Lãi khi bán khoảng <b>${profit.toLocaleString('vi-VN')} xu</b></p><p class="lake-help">Chọn mồi, chạm chỗ trống để thả. Khi phao báo cá cắn, chạm để thu cá về kho. Bạn có thể về vườn trong lúc chờ.</p><footer class="lake-footer"><button data-action="expandPond" ${s.fishing.length>=8?'disabled':''}>Mở chỗ câu</button><button data-action="bag">Kho / Bán cá</button></footer>`:`<div class="lake-net-summary"><strong>${s.pond.nets.length} vị trí thả lưới</strong><p>Chờ lưới đầy rồi thu cá, tôm, cua về kho. Nâng ao để mở thêm thủy sản.</p><button class="primary" data-action="nets">${ready?'Thu lưới / Thả lưới mới':'Chọn loại lưới'}</button><button data-action="bag">Kho / Bán thủy sản</button></div>`}</section>`}

// ---- Lake: what you see while fishing ----
// Spots sit on the water; the fisher's rod tip is at about (38 %, 66 %) of the lake picture.
let justCast=-1,justNet=-1;
const lakeSpot=i=>`--spot-x:${20+(i%4)*20}%;--spot-y:${35+Math.floor(i/4)*23}%`,NET_SPOTS=[[27,40],[60,36],[52,63],[83,57]],netSpot4=i=>`--spot-x:${NET_SPOTS[i][0]}%;--spot-y:${NET_SPOTS[i][1]}%`;
// fishing lines from the rod tip to every float in the water, sagging a little
function lakeLines(){const lines=s.fishing.map((t,i)=>{if(!t)return '';const x=20+(i%4)*20,y=35+Math.floor(i/4)*23;return `<path d="M38 66 Q${(38+x)/2} ${Math.min(y,66)-12} ${x} ${y-4}"/>`}).join('');return lines?`<svg class="lake-lines" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${lines}</svg>`:''}
// A cast net as it lies on the water: diamond mesh, a cork-float rope round the rim and lead weights sinking the edge.
const NET_MESH=(id,c)=>`<pattern id="${id}" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0H8M0 0V8" stroke="${c}" stroke-width="1.1" fill="none"/></pattern>`;
const NET_SVG=`<svg viewBox="-60 -60 120 120"><defs>${NET_MESH('lakeMesh','#fbf6e6')}<radialGradient id="lakeNetWater"><stop offset="0" stop-color="#2f6f86" stop-opacity=".35"/><stop offset="1" stop-color="#2f6f86" stop-opacity="0"/></radialGradient></defs><circle r="56" fill="url(#lakeNetWater)"/><circle r="50" fill="url(#lakeMesh)" opacity=".8"/>${Array.from({length:8},(_,k)=>{const a=k*Math.PI/4;return `<path d="M0 0 Q${(25*Math.cos(a+.2)).toFixed(1)} ${(25*Math.sin(a+.2)).toFixed(1)} ${(50*Math.cos(a)).toFixed(1)} ${(50*Math.sin(a)).toFixed(1)}" stroke="#efe6c8" stroke-width="1.4" fill="none" opacity=".9"/>`}).join('')}<circle r="50" fill="none" stroke="#7a5a36" stroke-width="2.4" stroke-dasharray="7 3"/>${Array.from({length:16},(_,k)=>{const a=k*Math.PI/8,x=(50*Math.cos(a)).toFixed(1),y=(50*Math.sin(a)).toFixed(1);return k%2?`<ellipse cx="${x}" cy="${y}" rx="4.5" ry="3" fill="#f2c063" stroke="#6b4a2e" stroke-width="1"/>`:`<circle cx="${x}" cy="${y}" r="2.6" fill="#55595e" stroke="#2b2c30" stroke-width=".8"/>`}).join('')}<circle r="3.5" fill="#6b4a2e"/></svg>`;
function castAt(i){justCast=i;clearTimeout(castAt.t);castAt.t=setTimeout(()=>{justCast=-1},1200);window.farmAudio?.effect('water')}
function netSpot(i){const n=s.pond.nets[i];if(!n)return showModal('nets');if(n.readyAt>Date.now())return toast('Lưới '+(i+1)+' chưa đầy · còn '+clock((n.readyAt-Date.now())/1000));haulNet(i)}
// Pull the net in: the catch goes to the bag first (nothing is lost if the dialog is closed), then the haul is shown
// with every animal caught in the mesh.
function haulNet(i){const n=s.pond.nets[i];if(!n||n.readyAt>Date.now())return;const kind=n.kind,d=F.netTypes[kind],before={...s.bag};if(modalView)close();if(!action({type:'collectNet',index:i}))return;
 const got=Object.keys(F.netTypes).map(k=>[k,s.bag[k]-(before[k]||0)]).filter(([,c])=>c>0).sort((a,b)=>(b[0]===kind)-(a[0]===kind)),animals=got.flatMap(([k,c])=>Array(c).fill(k));
 // spots inside the hanging net, filled from the bottom of the bag up
 const spots=[[50,80],[38,74],[62,74],[30,63],[50,64],[70,63],[24,51],[40,53],[60,53],[76,51],[33,41],[50,42],[67,41],[44,31],[58,31]],
 catches=animals.map((k,j)=>{const [x,y]=spots[j%spots.length];return `<span class="haul-catch ${k===kind?'':'bonus'}" style="left:${x+(j>=spots.length?4:0)}%;top:${y-(j>=spots.length?3:0)}%;--r:${(j*47%70)-35}deg;--hue:${k==='fish'?(j*67%160)-50:0}deg;--d:${(j*.13).toFixed(2)}s">${image(k)}</span>`}).join('');
 const bag='M100 8 C78 40 34 52 18 92 C10 116 26 150 52 158 C78 166 122 166 148 158 C174 150 190 116 182 92 C166 52 122 40 100 8Z';
 modal('Mẻ lưới · '+d.name,`<div class="haul-view"><svg class="haul-net back" viewBox="0 0 200 170" aria-hidden="true"><defs>${NET_MESH('haulMeshB','#8fb6c2')}</defs><path d="${bag}" fill="#bfe1ea66"/><path d="${bag}" fill="url(#haulMeshB)" opacity=".6"/></svg>${catches}<svg class="haul-net front" viewBox="0 0 200 170" aria-hidden="true"><defs>${NET_MESH('haulMeshF','#fbf6e6')}<clipPath id="haulBag"><path d="${bag}"/></clipPath></defs><g clip-path="url(#haulBag)"><rect width="200" height="170" fill="url(#haulMeshF)" opacity=".85"/></g>${[[100,8,40,130],[100,8,160,130],[100,8,100,165]].map(([x0,y0,x1,y1])=>`<path d="M${x0} ${y0} Q${(x0+x1)/2+(x1-x0)*.15} ${(y0+y1)/2} ${x1} ${y1}" stroke="#efe6c8" stroke-width="1.6" fill="none"/>`).join('')}<path d="${bag}" fill="none" stroke="#6b4a2e" stroke-width="2.4"/><path d="M100 8 L100 -6" stroke="#7a5a36" stroke-width="4" stroke-linecap="round"/>${Array.from({length:11},(_,k)=>{const t=k/10,x=(26+148*t).toFixed(1),y=(150+Math.sin(t*Math.PI)*13).toFixed(1);return `<circle cx="${x}" cy="${y}" r="3.6" fill="#55595e" stroke="#2b2c30"/>`}).join('')}${Array.from({length:6},(_,k)=>`<circle class="haul-drip" cx="${40+k*24}" cy="${160+(k%2)*4}" r="2.2" fill="#9fd8ea" style="--k:${k}"/>`).join('')}</svg></div><p class="haul-total">Mắc lưới: ${got.map(([k,c])=>`<b>${c} ${F.goods[k].name}</b>`).join(' · ')} · +${d.xp} XP · đã cho vào kho</p><button class="primary full" data-action="nets">Thả lưới mới</button><button class="text-link full" data-action="close">Về hồ</button>`,'haul');}
function netsDialog(){modal('Thả lưới · Ao cấp '+s.pond.level,`<p class="modal-note">Câu cá và thả lưới hoạt động độc lập. Chọn loại lưới, chờ đầy rồi kéo về kho để bán. Lưới vẫn tiến triển khi đóng game.</p>${s.pond.nets.map((n,i)=>`<article class="net-card"><h3>Vị trí lưới ${i+1}</h3>${n?`<div class="net-catch">${image(n.kind)}<div><strong>${F.netTypes[n.kind].name}</strong><p>${n.readyAt<=Date.now()?'Lưới đã đầy!':'Còn '+countdown(n.readyAt)}</p><small>Nhận ${F.netTypes[n.kind].amount} ${F.goods[n.kind].name} + 1–3 thủy sản ngẫu nhiên · +${F.netTypes[n.kind].xp} XP</small></div></div><button class="primary full" data-action="haulNet" data-index="${i}" ${n.readyAt>Date.now()?'disabled':''}>Kéo lưới</button>`:`<div class="net-options">${Object.entries(F.netTypes).map(([k,d])=>`<button data-action="castNet" data-key="${k}" data-index="${i}" ${s.pond.level<d.tier||s.coins<d.cost?'disabled':''}>${image(k)}<strong>${d.name}</strong><small>${s.pond.level<d.tier?'Mở khi ao cấp '+d.tier:d.cost+' xu · '+clock(d.time)}</small><small>${d.amount} ${F.goods[k].name} + ngẫu nhiên</small></button>`).join('')}</div>`}</article>`).join('')}<div class="pond-links"><button data-action="pondUpgrade">Nâng cấp ao</button><button data-action="bag">Bán cá, tôm, cua</button></div>`,'nets')}
function pondUpgradeDialog(){const u=F.pondUpgrades[s.pond.level];modal('Nâng cấp ao',`<p class="modal-note">Ao hiện tại: <b>cấp ${s.pond.level}</b>. Nâng ao mở loại thủy sản mới và thêm chỗ thả lưới (tối đa 4 lưới lớn). Những lưới đang thả vẫn được giữ.</p><div class="pond-tiers">${Object.entries(F.netTypes).map(([k,d])=>`<div class="pond-tier ${s.pond.level>=d.tier?'available':''}">${image(k)}<div><strong>Ao cấp ${d.tier} · ${Math.min(4,d.tier)} vị trí lưới</strong><small>${d.name}${d.tier>1?' · Nhân vật cấp '+F.pondUpgrades[d.tier-1].level+' · '+F.pondUpgrades[d.tier-1].cost+' xu':''}</small></div><span>${s.pond.level>=d.tier?'Đã mở':'Chưa mở'}</span></div>`).join('')}</div>${u?`<button class="primary full" data-action="upgradePond" ${F.level(s)<u.level||s.coins<u.cost?'disabled':''}>Nâng ao lên cấp ${s.pond.level+1} · ${u.cost} xu</button><p class="modal-note">Cần nhân vật cấp ${u.level}; bạn đang cấp ${F.level(s)}, có ${s.coins} xu.</p>`:'<p class="modal-note">Ao đã đạt cấp 8 tối đa.</p>'}<button class="text-link full" data-action="nets">Về khu thả lưới</button>`,'pondUpgrade')}
function workshopScene(){return `<div class="workshop-scene">${image('workshop','workshop-art')}<div class="workshop-board"><h3>Góc bánh & mứt của ${esc(s.profile.name||'bạn')}</h3><p>${Object.keys(s.jobs).length?Object.keys(s.jobs).length+' mẻ đang chế biến':'Nguyên liệu từ vườn, món ngon từ tay bạn.'}</p><button class="primary" data-action="recipes">Mở sổ công thức</button><div class="job-list">${Object.entries(s.jobs).map(([k,t])=>`<button data-action="craft" data-key="${k}" ${t>Date.now()?'disabled':''}>${image(k)}<span>${F.recipes[k].name}<small>${t<=Date.now()?'Đã xong · Nhận':countdown(t)}</small></span></button>`).join('')}</div></div></div>`}
function marketScene(){return `<div class="market-scene"><div class="market-banner">Tạp hoá Làng Mây<small>Nông sản nhà trồng, gửi đến mọi người</small></div><div class="market-options"><button data-action="shop">${icon('seedbag','market-art')}<strong>Quầy hạt giống</strong><span>23 loại cây · Mở dần theo cấp</span></button><button data-action="orders">${icon('clipboard','market-art')}<strong>Bảng đặt hàng</strong><span>Giao hàng nhận xu & kinh nghiệm</span></button><button data-action="bag">${icon('coins','market-art')}<strong>Quầy thu mua</strong><span>Bán nông sản đã thu hoạch lấy xu</span></button></div><div class="market-options"><button data-action="pantry"><span class="market-art" aria-hidden="true">🥩</span><strong>Thịt & gia vị</strong><span>Nguyên liệu cho nhà bếp</span></button></div>${shoppingScene()}</div>`}
// Outfits drawn with tall boots get a bare-legged picture (tools/art/shod-legs.cjs) while shop shoes are worn, so the
// boots never show behind the new pair.
const SHOD_OUTFITS=new Set(['denim','denimjacket','green','master','jade','legend']);
function rigSrc(gender,k,shoe=s.footwear.equipped){return `fashion/rig-${gender}-${k}${shoe!=='bare'&&SHOD_OUTFITS.has(k)?'-shod':''}.png?v=47.3`}
window.rigSrc=rigSrc;
// Where a fitted shoe starts (shoe-fit.js, made by tools/art/shoe-fit.py): the footwear painted in the outfit is cut away
// from there down, so only the chosen shoe shows. A still picture is cut at the lower of the two shoe tops.
window.shoeCut=(g,k,shoe)=>{const f=window.XOM_SHOE_FIT?.[g+'-'+k+'-'+shoe];return f?Math.max(f.t[0],f.t[1])+10:0};
// Still pictures are stacked like the walking character: legs (below the shoes), the shoes, then the body down to the
// hips ON TOP of the shoes, so shorts, skirts and trouser hems stay over the tops of tall boots. dollClips() gives the
// clip of each body copy (400-row layer units); null means no shoes are worn and the whole picture is used.
function dollClips(g,k,shoe){const j=window.XOM_RIG_JOINTS?.['rig-'+g+'-'+k],cut=shoe==='bare'?0:shoeCut(g,k,shoe);if(!j||!cut)return null;const hip=Math.min(j.crotch+3,cut),top=j.crotch-8,inset=(a,b)=>'clip-path:inset('+(a/4).toFixed(2)+'% 0 '+((400-b)/4).toFixed(2)+'% 0)';return {upper:inset(0,hip),legs:cut>top+3?inset(top,cut):''}}
const cutStyle=(g,k,shoe)=>{const c=dollClips(g,k,shoe);return c?' style="'+c.upper+'"':''};
// 3D picture spec read by world3d.js (data-c3d): the painted layers stay inside the element as the fallback.
// hat: the player's own by default; '' leaves it to the outfit (others' characters whose hat we don't know)
function c3dChar(gender,k,shoe,pose='',hair=s.appearance.hair,hat=s.headwear?.equipped){const L=window.AvatarRig?.look({gender,outfit:k,hair,shoe,modular:F.outfits[k]?.modular!==undefined})||{};return ['char',gender==='male'?'male':'female',k,L.hair||'',L.shoe||'',pose,...(hat?[hat]:[])].join(':')}
const PET_3D={'black-cat':'cat','black-dog':'dog',lion:'lion',pigeon:'pigeon'};
function outfitArt(k,gender=s.profile.gender,shoe=s.footwear.equipped){const d=F.outfits[k];if(d.modular!==undefined)return modularArt(k,gender,s.appearance.hair,shoe);const src=rigSrc(gender,k,shoe),c=dollClips(gender,k,shoe);return `<span class="rig-preview outfit-preview" role="img" aria-label="${esc(d.name)}" data-c3d="${c3dChar(gender,k,shoe)}">${c?`${c.legs?`<img class="doll-legs" src="${src}" alt="" style="${c.legs}">`:''}<img class="preview-shoes" src="fashion/feet-${gender}-${k}-${shoe}.png?v=49.0" alt=""><img class="doll-upper" src="${src}" alt="" style="${c.upper}">`:`<img src="${src}" alt="">`}</span>`}
function wardrobeDialog(){modal('Tiệm may · Tủ quần áo',`<p class="modal-note">Trang phục thưởng ở cấp 5, 15, 30, 50, 100, 150 và 200. Có thể mặc ngay từ tủ; tiệm may mở trong Tạp hoá ở cấp 10.</p><button class="house-secondary full" data-custom="hair">Chọn kiểu tóc</button><div class="wardrobe-grid">${Object.entries(F.outfits).map(([k,d])=>`<article>${outfitArt(k)}<strong>${d.name}</strong><small>Cấp ${d.level}${s.wardrobe.owned.includes(k)?' · Đã sở hữu':d.rewardOnly?' · Quà mốc cấp':' · '+d.cost+' xu'}</small><button class="primary" data-action="${s.wardrobe.owned.includes(k)?'equipOutfit':'buyOutfit'}" data-key="${k}" ${s.wardrobe.equipped===k||!s.wardrobe.owned.includes(k)&&(d.rewardOnly||!s.unlocked.shopping||F.level(s)<d.level||s.coins<d.cost)?'disabled':''}>${s.wardrobe.equipped===k?'Đang mặc':s.wardrobe.owned.includes(k)?'Mặc trang phục':'Mua'}</button></article>`).join('')}</div>`,'wardrobe')}
function shoeArt(k){return k==='bare'?'<span class="shoe-bare" aria-label="Chân trần">—</span>':`<img class="shoe-preview" src="fashion/preview-shoes-${k}.png?v=47.1" alt="${F.footwear[k].name}">`}
function shoesDialog(){modal('Tiệm giày dép',`<p class="modal-note">Mua giày bằng xu và mang cùng bất kỳ bộ quần áo nào. Trang bị được lưu khi mở lại game.</p><div class="wardrobe-grid">${Object.entries(F.footwear).map(([k,d])=>`<article><span class="shoe-try">${outfitArt(s.wardrobe.equipped,s.profile.gender,k)}${k==='bare'?'':`<img class="shoe-badge" src="fashion/preview-shoes-${k}.png?v=47.1" alt="">`}</span><strong>${d.name}</strong><small>Cấp ${d.level}${s.footwear.owned.includes(k)?' · Đã sở hữu':d.rewardOnly?' · Quà mốc cấp':' · '+d.cost+' xu'}</small><button class="primary" data-action="${s.footwear.owned.includes(k)?'equipShoes':'buyShoes'}" data-key="${k}" ${s.footwear.equipped===k||!s.footwear.owned.includes(k)&&(d.rewardOnly||!s.unlocked.shopping||F.level(s)<d.level||s.coins<d.cost)?'disabled':''}>${s.footwear.equipped===k?'Đang mang':s.footwear.owned.includes(k)?'Mang đôi này':'Mua'}</button></article>`).join('')}</div>`,'shoes')}
// Tiệm nón: hats are sold apart from outfits; each card shows your character (head and shoulders, 3D) wearing it.
const HAT_ICON={none:'🙂',nonla:'👒',cap:'🧢',bucket:'🪣',beanie:'🧶',straw:'👒',beret:'🎨',sunhat:'👒',catears:'🐱',fedora:'🎩',bowler:'🎩',cowboy:'🤠',flower:'🌸'};
function hatsDialog(){const h=s.headwear;modal('Tiệm nón',`<p class="modal-note">Nón bán riêng, đội cùng bất kỳ bộ quần áo nào. Trang bị được lưu khi mở lại game.</p><div class="wardrobe-grid hat-grid">${Object.entries(F.headwear).map(([k,d])=>{const own=h.owned.includes(k);return `<article><span class="shoe-try hat-try" data-c3d="${c3dChar(s.profile.gender,s.wardrobe.equipped,s.footwear.equipped,'head',s.appearance.hair,k)}"><span class="hat-icon" aria-hidden="true">${HAT_ICON[k]||'🎩'}</span></span><strong>${d.name}</strong><small>${k==='none'?'Để đầu trần':'Cấp '+d.level+(own?' · Đã sở hữu':' · '+(d.cost?d.cost+' xu':'Miễn phí'))}</small><button class="primary" data-action="${own?'equipHat':'buyHat'}" data-key="${k}" ${h.equipped===k||!own&&(!s.unlocked.shopping||F.level(s)<d.level||s.coins<d.cost)?'disabled':''}>${h.equipped===k?(k==='none'?'Đang để đầu trần':'Đang đội'):own?(k==='none'?'Bỏ nón':'Đội nón này'):'Mua'}</button></article>`}).join('')}</div>`,'hats')}
function suppliesDialog(){modal('Quầy vật tư · Túi nhân vật',`<p class="modal-note">Phân bón được tặng mỗi 5 cấp. Tạp hoá bán vật tư từ cấp 10 và sổ kinh nghiệm từ cấp 20.</p>${Object.entries(F.supplies).map(([k,d])=>`<article class="recipe-card"><h3>${d.name} ×${s.items[k]}</h3><p>${d.desc}</p><button data-action="buyItem" data-key="${k}" ${!s.unlocked.shopping||F.level(s)<d.level||s.coins<d.cost?'disabled':''}>Mua · ${d.cost} xu · Cấp ${d.level}</button>${k==='xpbook'?`<button data-action="useItem" data-key="${k}" ${!s.items[k]?'disabled':''}>Đọc sổ · +100 XP</button>`:`<div class="fertilizer-targets">${s.plots.map((p,i)=>p?.water&&F.remaining(p)>0?`<button data-action="useItem" data-key="fertilizer" data-index="${i}" ${!s.items.fertilizer?'disabled':''}>Bón ô ${i+1} · ${F.crops[p.crop].name}</button>`:'').join('')}</div>`}</article>`).join('')}`,'supplies')}
function wholesaleDialog(){modal('Chợ sỉ · Cấp 25',`<p class="modal-note">Mua 10 hạt cùng loại, giảm 10% giá. Cần mở Tạp hoá và đạt cấp 25.</p>`+Object.entries(F.crops).map(([k,c])=>`<div class="store-row">${cropImage(k)}<div><strong>${c.name}</strong><small>Có ${s.seeds[k]} hạt · Cấp ${c.level}</small></div><button data-action="buyBundle" data-key="${k}" ${!s.unlocked.shopping||F.level(s)<Math.max(25,c.level)||s.coins<Math.ceil(c.buy*9)?'disabled':''}>10 hạt · ${Math.ceil(c.buy*9)} xu</button></div>`).join(''),'wholesale')}
function shoppingScene(){return `<div class="market-scene shopping-scene"><div class="market-banner">Thời trang & vật tư<small>Tiệm may · Giày dép · Nón · Vật tư · Chợ sỉ</small></div><div class="market-options"><button data-action="wardrobe">${outfitArt(s.wardrobe.equipped)}<strong>Tiệm may</strong><span>Quần áo mua & quà mốc cấp</span></button><button data-custom="hair"><span class="market-art">✂️</span><strong>Tiệm tóc</strong><span>8 kiểu tóc miễn phí</span></button><button data-action="shoes">${shoeArt(s.footwear.equipped==='bare'?'sneakers':s.footwear.equipped)}<strong>Tiệm giày dép</strong><span>6 đôi để mua & trang bị</span></button><button data-action="hats"><span class="market-art">👒</span><strong>Tiệm nón</strong><span>${Object.keys(F.headwear).length-1} kiểu nón để mua & đội</span></button><button data-action="supplies">${image('watering','market-art')}<strong>Quầy vật tư</strong><span>Phân bón cấp 10 · Sổ XP cấp 20</span></button><button data-action="wholesale">${icon('crate','market-art')}<strong>Chợ sỉ</strong><span>Giảm 10% cho gói hạt · Cấp 25</span></button></div></div>`}
function render(){const lvl=F.level(s);$('level').textContent=lvl;$('xp').max=lvl===F.MAX_LEVEL?1:F.threshold(lvl+1)-F.threshold(lvl);$('xp').value=lvl===F.MAX_LEVEL?1:Math.min($('xp').max,s.xp-F.threshold(lvl));$('xpText').textContent=lvl===F.MAX_LEVEL?'CẤP TỐI ĐA':lvl>=F.progressionStart(s)&&s.xp>=F.threshold(lvl+1)?'NHIỆM VỤ':`${s.xp-F.threshold(lvl)} / ${$('xp').max} XP`;$('coins').textContent=Math.floor(s.coins).toLocaleString('vi-VN');$('profileLabel').textContent=s.profile.name||'Tạo nhân vật của bạn';$('playerLabel').textContent=s.profile.name||'Bạn';$('playerArt').src=s.profile.gender==='male'?'farmer-male.png':'farmer.png';const outfit=F.outfits[s.wardrobe.equipped];$('avatar').classList.toggle('modular-avatar',outfit.modular!==undefined);const shoeFit={width:100,left:0,bottom:0};for(const [k,v]of Object.entries(shoeFit))$('playerRig').style.setProperty?.('--shoe-'+k,v+'%');if(outfit.atlas)$('playerArt').src='fashion/'+s.profile.gender+'-'+s.wardrobe.equipped+'.png';else if(outfit.style>=0)$('playerArt').src='data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';$('playerArt').style.visibility='visible';$('playerArt').style.filter='none';$('playerArt').style.backgroundImage=outfit.style<0||outfit.atlas?'none':'url(outfit-atlas.png)';$('playerArt').style.backgroundSize='400% 200%';$('playerArt').style.backgroundPosition=outfit.style*100/3+'% '+(s.profile.gender==='male'?100:0)+'%';if(outfit.modular!==undefined){$('playerArt').src='data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';$('playerArt').style.backgroundImage='url(fashion/body-'+s.profile.gender+'-'+outfit.modular+'.png?v=47.0)';$('playerArt').style.backgroundSize='100% 100%';$('playerArt').style.backgroundPosition='center';}$('playerArt').src='data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';$('playerArt').style.backgroundImage='url('+rigSrc(s.profile.gender,s.wardrobe.equipped)+')';$('playerArt').style.backgroundSize='100% 100%';$('playerArt').style.backgroundPosition='center';for(const id of ['playerHair','playerHairBack']){const layer=$(id);layer.hidden=outfit.modular===undefined;layer.style.display=outfit.modular===undefined?'none':'block';layer.style.backgroundImage='url(fashion/hair-'+s.appearance.hair+(id==='playerHair'?'-front':'')+'.png?v=47.0)';layer.style.backgroundPosition='center';layer.style.backgroundSize='100% 100%';}$('playerShoes').hidden=s.footwear.equipped==='bare';$('playerShoes').style.display=s.footwear.equipped==='bare'?'none':'block';if(s.footwear.equipped!=='bare')$('playerShoes').src='fashion/feet-'+s.profile.gender+'-'+s.wardrobe.equipped+'-'+s.footwear.equipped+'.png?v=47.1';$('playerShoes').alt=s.footwear.equipped==='bare'?'':F.footwear[s.footwear.equipped].name;if(s.zone==='farm'){const wr=$('world').getBoundingClientRect?.(),av=$('avatar').getBoundingClientRect?.();if(wr?.width&&wr?.height&&av?.height){const mx=av.width/2/wr.width*100+1;s.pos.x=Math.max(mx,Math.min(100-mx,s.pos.x));s.pos.y=Math.max(av.height/wr.height*100+1,Math.min(97,s.pos.y));}}$('avatar').style.left=s.pos.x+'%';$('avatar').style.setProperty?.('--walker-x',s.pos.x+'%');$('avatar').style.top=s.pos.y+'%';$('avatar').style.setProperty?.('--walker-y',s.pos.y+'%');$('avatar').style.display=['pond','market','shopping','kitchen','leisure','home','cafe','beauty','karaoke','pets','street'].includes(s.zone)?'none':'';$('scenery').src=s.zone==='pond'?'pond-hd.webp':'farm-hd.webp';$('world').className='world zone-'+s.zone;$('world').style.setProperty?.('--field-cols',String(s.plots.length<=16?4:s.plots.length<=36?6:8));$('world').style.setProperty?.('--field-rows',String(Math.ceil(Math.min(48,s.plots.length)/(s.plots.length<=16?4:s.plots.length<=36?6:8))));$('world').style.setProperty?.('--mobile-field-cols',String(s.plots.length<=16?4:6));$('world').style.setProperty?.('--mobile-field-rows',String(Math.ceil(s.plots.length/(s.plots.length<=16?4:6))));
html('zoneNav',`<button class="ranking-tab" data-ranking="open"><span>🏆</span>Top 10</button><button class="village-nav ${s.zone==='village'?'active':''}" data-action="travel" data-key="village"><span>🏘️</span>Làng</button>`+Object.entries(F.zones).filter(([k,z])=>!z.hidden&&k!=='village').map(([k,z])=>`<button class="${s.zone===k?'active':''} ${s.unlocked[k]?'':'zone-locked'}" data-action="travel" data-key="${k}"><span>${z.icon}</span>${z.name}<small>${s.unlocked[k]?'':`🔒 Cấp ${z.level}`}</small></button>`).join(''));$('zoneLabel').textContent=F.zones[s.zone].name;
html('scene',({farm:farmScene,street:()=>window.streetScene?.()||'<div class=street-loading>Đang mở phố đi bộ…</div>',village:villageScene,barn:barnScene,pond:pondScene,workshop:workshopScene,market:marketScene,shopping:shoppingScene,kitchen:kitchenScene,leisure:entertainmentScene,home:homeScene,cafe:()=>venueScene('cafe'),beauty:()=>venueScene('beauty'),karaoke:()=>venueScene('karaoke'),pets:petShopScene}[s.zone])());
syncFieldPager();
let active=F.missions.filter(m=>!s.claimed.includes(m.id)).slice(0,3);html('tasks',active.map(m=>`<div class="task ${progress(m)>=m.target?'done':''}"><span>${progress(m)>=m.target?'✓':'○'}</span><div>${m.name}<small>${progress(m)} / ${m.target} · +${F.income(s,m.coins)} xu</small></div>${progress(m)>=m.target?`<button data-action="claim" data-key="${m.id}" aria-label="Nhận thưởng ${m.name}">Nhận</button>`:''}</div>`).join('')+`<button class="all-quests" data-action="quests">${active.length?'Tất cả nhiệm vụ':'Đã xong hành trình! Xem việc hằng ngày'}</button>`);
$('workShortcut').textContent=s.work.active?(s.work.active.readyAt<=Date.now()?'Nhận tiền công':'Việc đang làm'):'Kiếm thêm xu';$('questBadge').textContent=claimable()||'';$('questBadge').hidden=!claimable();
html('quickPanel',s.zone==='farm'?`${image('chicken')}<div><strong>Gà Mơ</strong><p>${animalText('chicken')}</p>${animalButton('chicken')}</div>`:`<div class="zone-tip"><strong>${F.zones[s.zone].name}</strong><p>${F.zones[s.zone].desc}</p><button class="text-link" data-action="quests">Nhiệm vụ & quà mỗi ngày</button></div>`);
$('landControl').hidden=s.zone!=='farm';$('landControl').textContent=s.plots.length<48?'Mở thêm đất · '+s.plots.length+'/48 ô':F.progressionStart(s)===50&&F.landExpansion(s)?'Mua thêm ô đất · '+F.landExpansion(s).cost.toLocaleString('vi-VN')+' xu':'Đã mở '+s.plots.length+' ô';$('seedTray').hidden=s.zone!=='farm';$('selectedSeedLabel').textContent=F.crops[seed].name+' · '+s.seeds[seed]+' hạt';html('seedList',Object.entries(F.crops).filter(([k,c])=>c.level<=lvl).map(([k,c])=>`<button class="seed-item ${seed===k?'active':''}" data-action="seed" data-key="${k}">${cropImage(k)}<span><strong>${c.name}</strong><small>${clock(c.time)}</small></span><b>×${s.seeds[k]}</b></button>`).join(''));
let farmTools=`<button data-action="tool" data-key="seed" class="${tool==='seed'?'selected':''}">${image('sprout')}Gieo hạt</button><button data-action="tool" data-key="water" class="${tool==='water'?'selected':''}">${image('watering')}Tưới nước</button><button data-action="tool" data-key="pest" class="${tool==='pest'?'selected':''}">${icon('bugnet')}Bắt sâu</button><button data-action="tool" data-key="harvest" class="${tool==='harvest'?'selected':''}">${image('basket')}Thu hoạch</button>`;
html('toolbar',(s.zone==='farm'?farmTools:`<button data-action="travel" data-key="farm">${image('sprout')}Về vườn</button><button data-action="${s.zone==='workshop'?'recipes':s.zone==='market'?'orders':'quests'}">${icon(s.zone==='workshop'?'book':s.zone==='market'?'clipboard':'checklist')}${s.zone==='workshop'?'Công thức':s.zone==='market'?'Đơn hàng':'Nhiệm vụ'}</button>`)+`<i></i><button data-action="shop">${icon('seedbag')}Mua hạt</button><button data-action="bag">${icon('crate')}Kho & bán</button>`);
$('toolCaption').textContent=s.zone==='farm'?{seed:F.crops[seed].name+' · Chạm ô đất trống để gieo',water:'Chạm cây mới gieo để tưới nước',pest:'Chạm cây có sâu để bắt sâu',harvest:'Chạm cây chín để thu hoạch vào kho'}[tool]:{street:'Chạm đường để đi dạo · Chạm người chơi để kết bạn',cafe:'Phục vụ đồ uống từ nông sản vườn nhà',beauty:'Làm tóc, làm móng và chăm sóc da',karaoke:'Đón khách vào phòng hát, nhận tiền và nâng cấp',home:'Cấp 70 · Xây nhà, mua nội thất và trang trí theo gu riêng',barn:'Cho ăn, chờ vật nuôi nghỉ rồi nhận sản phẩm',pond:'Thả câu hoặc thả lưới · Nâng ao mở thêm tôm và cua',workshop:'Chế biến nông sản để tăng giá trị',market:'Đơn hàng thưởng thêm xu và kinh nghiệm',shopping:'Chọn tiệm may, quầy vật tư hoặc chợ sỉ',kitchen:'Chọn món Việt, chuẩn bị nguyên liệu và bắt đầu nấu',leisure:'Cấp 50 · Chọn trò, sẵn sàng và chơi cùng máy hoặc bạn bè'}[s.zone];tickSignature=signature()}
function signature(){return JSON.stringify([s.zone,s.daily.date,Object.values(s.town).map(v=>[v.level,v.jobs.map(j=>j.readyAt<=Date.now())]),s.kitchen.level,s.kitchen.jobs.map(j=>[j.dish,j.readyAt<=Date.now()]),s.work.active?.key,s.work.active?.readyAt<=Date.now(),s.plots.map(p=>p?[p.water,p.pest,F.remaining(p)===0,cropStage(p).key]:null),Object.values(s.animals).map(a=>!!a.readyAt&&a.readyAt<=Date.now()),s.fishing.map(t=>!!t&&t<=Date.now()),s.pond.level,s.pond.nets.map(n=>n?[n.kind,n.readyAt<=Date.now()]:null),Object.values(s.jobs).map(t=>t<=Date.now())])}
function modal(title,body,type){modalView=type;$('modalTitle').textContent=title;$('modalBody').innerHTML=body;if(!$('modal').open)$('modal').showModal()}
function close(){if(!s.profile.name){toast('Bạn hãy đặt tên để bắt đầu nhé.');return}$('modal').close();modalView=''}
function requirement(needs){return Object.entries(needs).map(([k,n])=>`<span class="ingredient ${s.bag[k]>=n?'enough':''}">${image(k)}<span>${F.goods[k].name}<small>${s.bag[k]} / ${n}</small></span></span>`).join('')}
function specialPanel(){const m=F.specialMission(s);if(!m)return `<p class="modal-note">${F.level(s)>=F.MAX_LEVEL?'Bạn đã đạt cấp 200!':'Nhiệm vụ đặc biệt mở từ cấp 100. Mỗi cấp sau đó cần đủ XP và hoàn thành nhiệm vụ mới được thăng cấp.'}</p>`;return `<section class="special-mission"><small>NHIỆM VỤ ĐẶC BIỆT · CẤP ${m.level} → ${m.next}</small><h3>${m.name}</h3><strong>Đã hoàn thành ${m.tasks.filter(t=>t.progress>=t.target).length}/${m.tasks.length} nhiệm vụ</strong>${m.level>=100?'<p>Phải hoàn thành đủ 10 nhiệm vụ và đủ XP mới được thăng cấp. Trang trí nông trại tính theo loại đồ khác nhau đã đặt.</p><button data-promotion-decor="open">Trang trí nông trại</button>':''}<p>Tiến độ tính từ lúc đạt cấp ${m.level}; không làm mới hằng ngày.</p>${m.tasks.map(a=>`<div class="special-target"><strong>${a.name}</strong><span>${a.progress} / ${a.target}</span><progress max="${a.target}" value="${a.progress}"></progress></div>`).join('')}<p>${m.xpReady?'Đã đủ kinh nghiệm':'Còn '+Math.max(0,F.threshold(m.next)-s.xp).toLocaleString('vi-VN')+' XP để thăng cấp'} · Thưởng ${m.coins.toLocaleString('vi-VN')} xu + 3 phân bón</p><button class="primary full" data-action="claimSpecial" ${m.ready&&m.xpReady?'':'disabled'}>Hoàn thành & thăng cấp ${m.next}</button><small>XP dư được giữ lại. Mỗi cấp có một nhiệm vụ riêng.</small></section>`}
function showModal(type){if(customizationModal(type))return;if(expansionModal(type))return;if(type==='land')return expand('Farm');if(type.startsWith('pen:'))return penDialog(type.slice(4));modalView=type;const lvl=F.level(s);switch(type){
case 'shoes':shoesDialog();break;case 'hats':hatsDialog();break;case 'wardrobe':wardrobeDialog();break;case 'supplies':suppliesDialog();break;case 'wholesale':wholesaleDialog();break;case 'nets':netsDialog();break;case 'pondUpgrade':pondUpgradeDialog();break;case 'work':workDialog();break;
case 'seeds':modal('Chọn hạt giống',`<p class="modal-note">Chọn hạt, rồi chạm ô đất trống để gieo. Vuốt xuống để xem thêm các loại đã mở khóa.</p><div class="seed-picker-grid">${$('seedList').innerHTML}</div><button class="primary full" data-action="shop">Mua thêm hạt giống</button>`,'seeds');break;
case 'shop':modal('Quầy hạt giống',`<p class="modal-note">Bạn có ${s.coins} xu. Mở thêm giống cây khi lên cấp.</p>`+Object.entries(F.crops).map(([k,c])=>`<div class="store-row">${cropImage(k)}<div><strong>${c.name}</strong><small>${clock(c.time)} · Bán ${F.sellPrice(s,k)} xu · Có ${s.seeds[k]} hạt</small>${lvl<c.level?`<small>🔒 Mở ở cấp ${c.level}</small>`:''}</div><div class="buy-buttons"><button data-action="buySeed" data-key="${k}" data-count="1" ${lvl<c.level||s.coins<c.buy?'disabled':''}>1 · ${c.buy} xu</button><button data-action="buySeed" data-key="${k}" data-count="5" ${lvl<c.level||s.coins<c.buy*5?'disabled':''}>5 · ${c.buy*5} xu</button></div></div>`).join(''),'shop');break;
case 'bag':{const total=Object.entries(s.bag).reduce((v,[k,n])=>v+n*F.sellPrice(s,k),0);modal('Quầy thu mua · Kho nông sản',`<p class="modal-note">Chọn loại nông sản bên dưới để bán lấy xu. Bạn cũng có thể giữ lại nguyên liệu cho đơn hàng và xưởng.</p><div class="inventory-grid">`+Object.entries(s.bag).filter(([k,n])=>n>0).map(([k,n])=>`<article>${image(k)}<strong>${F.goods[k].name} ×${n}</strong><small>${F.sellPrice(s,k)} xu / món</small><label for="sell-${k}">Số lượng bán</label><input id="sell-${k}" type="number" min="1" max="${n}" step="1" value="1"><button data-action="sell" data-key="${k}">Bán số lượng đã chọn</button><small>Giữ lại phần còn lại trong kho</small></article>`).join('')+`</div>${total?'':'<div class="empty-state">Giỏ của bạn còn trống.<br>Thu hoạch cây hoặc nhận sản phẩm từ vật nuôi nhé.</div>'}<button class="primary full" data-action="sellAllConfirm" ${!total?'disabled':''}>Bán toàn bộ · ${total} xu</button>`,'bag');break}
case 'quests':{if(questTab==='weekly'){weeklyDialog();break}if(questTab==='special'){modal('Nhật ký · Nhiệm vụ đặc biệt',`<div class="modal-tabs"><button data-action="questTab" data-key="journey">Hành trình</button><button data-action="questTab" data-key="daily">Hằng ngày</button><button class="active" data-action="questTab" data-key="special">Đặc biệt · 100+</button></div>${specialPanel()}`,'quests');break}const d=questTab==='daily',list=d?F.dailyFor(s):F.missions,claims=d?s.daily.claimed:s.claimed;modal('Nhật ký nhà nông',`<div class="modal-tabs"><button data-action="questTab" data-key="journey" class="${!d?'active':''}">Hành trình</button><button data-action="questTab" data-key="daily" class="${d?'active':''}">Hằng ngày</button><button data-action="questTab" data-key="weekly">Chuyện làng · Tuần</button><button data-action="questTab" data-key="special">Đặc biệt · 100+</button></div>${d?`<div class="daily-gift"><span>Quà ghé làng<br><small>${F.income(s,50)} xu + 2 hạt cà rốt</small></span><button class="primary" data-action="gift" ${s.daily.gift?'disabled':''}>${s.daily.gift?'Đã nhận':'Nhận quà'}</button></div><p class="modal-note">Luân phiên 4 việc mỗi ngày · Còn ${Math.max(0,F.threshold(Math.min(F.MAX_LEVEL,lvl+1))-s.xp).toLocaleString('vi-VN')} XP để đạt cấp ${Math.min(F.MAX_LEVEL,lvl+1)}. Làm mới lúc 00:00 giờ Việt Nam.</p>`:''}`+list.map(m=>`<div class="mission-row"><div><strong>${m.name}</strong><small>${progress(m,d)} / ${m.target} · ${F.missionReward(s,m,d).coins} xu + ${Math.floor(F.missionReward(s,m,d).xp*(lvl>=70?.9:1))} XP</small><progress value="${progress(m,d)}" max="${m.target}"></progress></div><button data-action="claim" data-key="${m.id}" data-daily="${d}" ${claims.includes(m.id)||progress(m,d)<m.target?'disabled':''}>${claims.includes(m.id)?'Đã nhận':'Nhận thưởng'}</button></div>`).join(''),'quests');break}
case 'orders':modal('Bảng đặt hàng',`<p class="modal-note">Đơn hàng thưởng cao hơn bán lẻ. Mỗi đơn giao một lần/ngày, làm mới lúc 00:00 giờ Việt Nam.</p>`+F.orders(s).map(o=>`<article class="recipe-card"><h3>${o.name}</h3><div class="ingredients">${requirement(o.needs)}</div><div class="recipe-footer"><span>+${o.coins} xu · +${Math.floor(o.xp*(lvl>=70?.9:1))} XP</span><button class="primary" data-action="order" data-key="${o.id}" ${s.daily.orders.includes(o.id)||Object.entries(o.needs).some(([k,n])=>s.bag[k]<n)?'disabled':''}>${s.daily.orders.includes(o.id)?'Đã giao':'Giao hàng'}</button></div></article>`).join(''),'orders');break;
case 'recipes':modal('Sổ công thức',`<p class="modal-note">Có thể làm nhiều món khác nhau cùng lúc. Nhận món đã hoàn thành trước khi bắt đầu mẻ mới.</p>`+Object.entries(F.recipes).map(([k,r])=>{const t=s.jobs[k];return `<article class="recipe-card"><h3>${image(k)} ${r.name} <small>Cấp ${r.level}</small></h3><div class="ingredients">${requirement(r.ingredients)}</div><div class="recipe-footer"><span>${t?t<=Date.now()?'Đã hoàn thành':countdown(t):clock(r.time)+' · Bán '+F.sellPrice(s,k)+' xu'}</span><button class="primary" data-action="craft" data-key="${k}" ${lvl<r.level||t>Date.now()||!t&&Object.entries(r.ingredients).some(([key,n])=>s.bag[key]<n)?'disabled':''}>${lvl<r.level?'Cấp '+r.level:t?t<=Date.now()?'Nhận món':'Đang làm…':'Chế biến'}</button></div></article>`}).join(''),'recipes');break;
case 'levels':modal('Hành trình cấp độ',`<p class="modal-note">Bạn đang ở cấp ${lvl}. Trồng trọt, chăm thú, câu cá, chế biến và hoàn thành nhiệm vụ để nhận kinh nghiệm.</p>${specialPanel()}<div class="level-list">`+Array.from({length:Number.isFinite(F.MAX_LEVEL)?F.MAX_LEVEL:200},(_,i)=>{const l=Number.isFinite(F.MAX_LEVEL)?i+1:Math.max(1,F.level(s)-100)+i,features=[...Object.values(F.zones).filter(z=>!z.hidden&&z.level===l).map(z=>z.name),...Object.values(F.crops).filter(c=>c.level===l).map(c=>'Hạt '+c.name),...Object.values(F.animals).filter(a=>a.level===l&&l>1).map(a=>a.name),...Object.values(F.recipes).filter(r=>r.level===l).map(r=>r.name),...Object.values(F.workTasks).filter(r=>r.level===l).map(r=>'Việc: '+r.name)];for(const [tier,u] of Object.entries(F.pondUpgrades))if(l===u.level)features.push('Ao cấp '+(Number(tier)+1)+' · '+(Number(tier)===1?'Lưới tôm':'Lưới cua'));if(l>100)features.push('Hoàn thành nhiệm vụ đặc biệt cấp '+(l-1));if(l===1)features.push('12 ô đất ban đầu');for(const [count,u]of Object.entries(F.landUpgrades))if(l===u.level)features.push('Mở đất lên '+(Number(count)+4)+' ô · '+u.cost+' xu');if([7,10,14].includes(l))features.push('Thêm chỗ câu');return `<div class="level-row ${l<=lvl?'achieved':''}"><b>${l}</b><div><strong>${features.join(' · ')||'Tiếp tục phát triển nông trại'}${l>1?' · Thưởng '+F.reward(l).coins+' xu + '+F.reward(l).seeds+' hạt '+F.crops[F.reward(l).crop].name+(F.reward(l).outfit?' + đồ '+F.outfits[F.reward(l).outfit].name:'')+(F.reward(l).furniture?' + '+F.furnishings[F.reward(l).furniture].name:'')+(F.reward(l).fertilizer?' + 2 phân bón':''):''}</strong><small>${l===F.MAX_LEVEL?'Cột mốc nhà nông làng Mây':F.threshold(l)+' XP tích lũy'}${l<=lvl?' · Đã đạt':''}</small></div></div>`}).join('')+'</div>','levels');break;
case 'profile':{profileGender=s.profile.gender;modal(s.profile.name?'Nhân vật của bạn':'Chào mừng đến Làng Mây!',`<p class="modal-note">Một miền quê nhỏ, một nhân vật của riêng bạn.</p><form id="profileForm"><div class="character-picker"><button type="button" data-action="gender" data-key="female" class="${profileGender==='female'?'chosen':''}"><span class="c3d-pick" data-c3d="char:female:base:::"><img src="farmer.png" alt="Nhân vật nữ"></span><strong>Nữ</strong></button><button type="button" data-action="gender" data-key="male" class="${profileGender==='male'?'chosen':''}"><span class="c3d-pick" data-c3d="char:male:base:::"><img src="farmer-male.png" alt="Nhân vật nam"></span><strong>Nam</strong></button></div><label class="name-label" for="characterName">Tên nhân vật</label><input id="characterName" name="name" autocomplete="off" maxlength="32" placeholder="Ví dụ: Hằng Mây" value="${esc(s.profile.name)}" required><small class="input-hint">Từ 1–18 ký tự. Có thể đổi tên và nhân vật bất cứ lúc nào.</small><button class="primary full" type="submit">${s.profile.name?'Lưu nhân vật':'Bắt đầu cuộc sống nhà nông'}</button></form>`,'profile');$('profileForm').onsubmit=e=>{e.preventDefault();if(action({type:'profile',name:$('characterName').value,gender:profileGender})){close();if(s.stats.planted===0){questTab='journey';showModal('help')}}};break}
case 'settings':modal('Lưu tiến độ & cài đặt',`<p class="modal-note">Trang trại và ván bài được lưu trực tuyến theo tài khoản. Đăng nhập cùng tài khoản để tiếp tục trên thiết bị khác.</p>${loadWarning?`<div class="error-box">${esc(loadWarning)}<button data-action="acceptFresh">Dùng nông trại mới này</button></div>`:''}${window.farmAudio?.panel()||''}<div class="settings-actions"><button data-action="syncSettings">Tài khoản & đồng bộ</button><button data-action="automation">Tự động trang trại / chăn nuôi</button><button data-action="wardrobe">Tủ quần áo</button><button data-custom="hair">Kiểu tóc</button><button data-action="supplies">Túi vật phẩm</button><a href="/admin" target="_top">Thống kê dành cho chủ game</a><button data-action="profile">Đổi tên / nhân vật</button><button data-action="export">Tải bản sao lưu (.json)</button><button data-action="import">Khôi phục từ bản sao lưu</button><button data-action="fullscreen">Bật / tắt toàn màn hình</button><button data-action="help">Hướng dẫn chơi</button></div><p class="modal-note">Làng Mây · 200 cấp · Trang trại và phố dịch vụ<br>Đồng bộ theo tài khoản · Chơi bài cùng máy.</p>`,'settings');break;
case 'help':modal('Bắt đầu ở Làng Mây',`<ol class="help-list"><li><b>Mở đất:</b> bắt đầu với 12 ô. Đạt cấp yêu cầu và dùng xu mở thêm 4 ô mỗi đợt, tối đa 48 ô ở cấp 40.</li><li><b>Trồng cây:</b> chọn hạt → chạm đất → tưới nước → bắt sâu nếu có → thu hoạch.</li><li><b>Lên cấp:</b> chăm vườn và nhận thưởng trong Nhật ký. Bấm huy hiệu cấp để xem nội dung mở khóa. Từ cấp 100, mỗi lần lên cấp cần đủ XP và hoàn thành nhiệm vụ đặc biệt trong Nhật ký.</li><li><b>Mở khu:</b> bấm khu có ổ khóa, đạt cấp và trả xu để mở. Gà Mơ có thể chăm ngay tại vườn.</li><li><b>Chuồng riêng:</b> vào chuồng gà, bò hoặc cừu để cho ăn, nhận sản phẩm và nâng chuồng.</li><li><b>Kiếm thêm xu:</b> nhận việc ở bảng Việc làm, chờ hoàn thành rồi nhận tiền công. Không cần vốn.</li><li><b>Ao cá:</b> thả câu hoặc thả lưới. Ao có 8 cấp, mở cá, tôm, cua, rô phi, lươn, tôm sú, nghêu và cá chép. Mỗi lần nâng thêm một chỗ thả lưới.</li><li><b>Nhà bếp · Bánh & mứt:</b> giữ nông sản làm bánh, mứt, phô mai; nhận món xong để làm mẻ tiếp.</li><li><b>Tự động:</b> mở cài đặt chăm vườn, chọn hạt và bật gieo, tưới, thu hoạch, bắt sâu. Dùng hạt có sẵn và hoạt động khi game đang mở.</li><li><b>Nhà bếp · Món Việt:</b> nấu món từ nông sản, mua thịt/gia vị, nâng bếp để nấu nhiều mẻ.</li><li><b>Bạn bè:</b> bấm 👥, tạo mã thăm trại hoặc nhập mã của bạn; tặng nông sản và tưới cây giúp nhau.</li><li><b>Chuyện làng:</b> vào Nhật ký → Chuyện làng · Tuần để nhận nhiệm vụ và lời cảm ơn từ dân làng.</li><li><b>Giải trí:</b> chọn Tiến lên, 3 cây hoặc Tá lả. Có luật và gợi ý trên bàn.</li><li><b>Tạp hoá:</b> bán nông sản hoặc giao đơn để nhận thêm xu và XP.</li></ol><p class="modal-note">Cây đã tưới, vật nuôi, cá và món ăn tiếp tục tiến triển khi đóng game. Chạm lối đi cạnh ruộng để di chuyển; trên máy tính dùng A/D hoặc mũi tên trái/phải. Đợi “Đã lưu trực tuyến” rồi đăng nhập cùng tài khoản khi chuyển máy. Không có mất mùa khi bạn vắng mặt.</p><button class="primary full" data-action="close">Về nông trại</button>`,'help');break}
}
function unlockDialog(z){const d=F.zones[z],lvl=F.level(s);modal('Mở '+d.name,`<div class="unlock-card"><span>${d.icon}</span><p>${d.desc}</p><div>Cấp yêu cầu: <b>${d.level}</b> · Bạn đang cấp <b>${lvl}</b></div><div>Chi phí: <b>${d.cost} xu</b> · Bạn có <b>${s.coins} xu</b></div><button class="primary full" data-action="unlock" data-key="${z}" ${lvl<d.level||s.coins<d.cost?'disabled':''}>Mở khu vực · ${d.cost} xu</button><button class="text-link" data-action="quests">Làm nhiệm vụ để nhận xu & XP</button></div>`,'unlock')}
function expand(kind){if(kind==='Farm'&&F.progressionStart(s)===50)return legacyExpand(kind);if(kind==='Farm'){const u=F.landUpgrades[s.plots.length];modal('Mở rộng đất · '+s.plots.length+'/48 ô',`<p class="modal-note">Mỗi đợt mở thêm 4 ô. Đạt cấp yêu cầu và dùng xu để mở; đất chưa mở không thể gieo trồng.</p>${u?`<button class="primary full" data-action="confirmExpandFarm" ${F.level(s)<u.level||s.coins<u.cost?'disabled':''}>Mở lên ${s.plots.length+4} ô · ${u.cost} xu</button><p class="modal-note">Cần cấp ${u.level}. Bạn đang cấp ${F.level(s)}, có ${s.coins} xu.</p>`:'<p>Đã mở tối đa 48 ô đất.</p>'}<div class="level-list">${Object.entries(F.landUpgrades).map(([count,u])=>`<div class="level-row ${s.plots.length>Number(count)?'achieved':''}"><b>${Number(count)+4}</b><div><strong>${Number(count)+4} ô đất</strong><small>Cấp ${u.level} · ${u.cost} xu ${s.plots.length>Number(count)?'· Đã mở':''}</small></div></div>`).join('')}</div>`,'land');return}const t=F.fishingUpgrades[s.fishing.length];if(!t)return toast('Bạn đã mở rộng tối đa.');modal('Mở rộng chỗ câu',`<div class="unlock-card"><p>Thêm 1 vị trí câu cá</p><p>Cần cấp ${t[0]} và ${t[1]} xu.</p><button class="primary full" data-action="confirmExpandPond" ${F.level(s)<t[0]||s.coins<t[1]?'disabled':''}>Mở rộng · ${t[1]} xu</button></div>`,'expand')}

function feedback(a,result,prev){if(['plot','animal','fish','collectNet','collectDish'].includes(a.type)){const avatar=$('avatar');avatar.classList.add('action-cheer');setTimeout(()=>avatar.classList.remove('action-cheer'),650);}let target;if(a.type==='plot')target=document.querySelector?.('[data-action="plot"][data-index="'+a.index+'"]');else if(['animal','buyAnimal','addAnimal'].includes(a.type))target=document.querySelector?.('[data-action="pen"][data-key="'+a.animal+'"]');else if(a.type==='fish')target=document.querySelector?.('[data-action="fish"][data-index="'+a.index+'"]');if(a.type==='animal'){document.querySelectorAll?.('.herd-animal').forEach(el=>el.animate?.([{transform:'translateY(0)'},{transform:'translateY(-6px)'},{transform:'translateY(0)'}],{duration:500}));}if(target){target.animate?.([{filter:'brightness(1)'},{filter:'brightness(1.35)'},{filter:'brightness(1)'}],{duration:360});const world=$('world');if(document.createElement&&world.appendChild){const mark=document.createElement('span'),r=target.getBoundingClientRect(),w=world.getBoundingClientRect();mark.className='action-feedback';mark.innerHTML=feedbackHTML(a,prev);mark.style.left=(r.left+r.width/2-w.left)+'px';mark.style.top=(r.top-w.top)+'px';world.appendChild(mark);setTimeout(()=>mark.remove(),1100)}}}
// What the floating label shows after an action: the actual crop / catch / product with the amount gained.
function feedbackHTML(a,prev){const gained=k=>Math.max(0,(s.bag[k]||0)-(prev.bag?.[k]||0)),emoji=e=>'<span class="fb-emoji">'+e+'</span>';
if(a.type==='plot'){if(a.tool==='water')return image('watering')+'Đã tưới';if(a.tool==='harvest'){const k=prev.plots[a.index].crop;return image(k)+'+'+Math.max(1,gained(k))+' '+esc(F.crops[k].name)}if(a.tool==='seed'){const k=s.plots[a.index]?.crop;return image('sprout')+'Đã gieo'+(k?' '+esc(F.crops[k].name):'')}return emoji('🐛')+'Đã bắt sâu'}
if(a.type==='fish')return s.fishing[a.index]?emoji('🎣')+'Đã thả câu':image('fish')+'+'+gained('fish')+' cá';
const k=a.animal,d=F.animals[k],prod=d?.product,n=prod?gained(prod):0;if(n>0)return image(prod)+'+'+n+' '+esc(F.goods[prod].name);if(a.type==='animal')return emoji('🌾')+'Đã cho '+esc(d?.name||'đàn')+' ăn';return (window.AvatarRig?.speciesOf('pens/'+k+'-animal.png')==='pig'?AvatarRig.animal('pig',{cls:'item-art',label:false}):'<img class="item-art" src="pens/'+k+'-animal.png" alt="">')+'Thêm '+esc(d?.name||'vật nuôi')}
function movePlayer(x,y=s.pos.y){if(!['farm','village','barn'].includes(s.zone)||window.farmSync?.blocked)return;const world=$('world'),r=world.getBoundingClientRect?.(),ar=$('avatar').getBoundingClientRect?.(),margin=r&&ar?Math.max(3,ar.width/2/r.width*100+1):5,top=r&&ar?Math.max(15,ar.height/r.height*100+1):20,target={x:Math.max(margin,Math.min(100-margin,x)),y:Math.max(top,Math.min(97,y))};if(r){const obstacles=[...document.querySelectorAll('.plot,.real-pen')].map(p=>p.getBoundingClientRect?.()).filter(Boolean);const sx=r.left+s.pos.x*r.width/100,sy=r.top+s.pos.y*r.height/100;if(obstacles.some(b=>sx>b.left-5&&sx<b.right+5&&sy>b.top-5&&sy<b.bottom+5))s.pos.y=97;let previous={...s.pos};for(let step=1;step<=30;step++){const p={x:s.pos.x+(target.x-s.pos.x)*step/30,y:s.pos.y+(target.y-s.pos.y)*step/30},px=r.left+p.x*r.width/100,py=r.top+p.y*r.height/100;if(obstacles.some(b=>px>b.left-5&&px<b.right+5&&py>b.top-5&&py<b.bottom+5)){target.x=previous.x;target.y=previous.y;break}previous=p;}}$('avatar').setAttribute('data-facing',target.x<s.pos.x?'left':'right');s.pos=target;walk();$('avatar').style.setProperty?.('--walker-x',s.pos.x+'%');$('avatar').style.setProperty?.('--walker-y',s.pos.y+'%');save()}

function walk(){const a=$('avatar');a.classList.add('walking');clearTimeout(walkTimer);walkTimer=setTimeout(()=>a.classList.remove('walking'),500)}
function travel(z){z=({workshop:'kitchen',shopping:'market'})[z]||z;if(!s.unlocked[z])return unlockDialog(z);if(action({type:'travel',zone:z})){if($('modal').open)close()}}
function backup(){const blob=new Blob([JSON.stringify({game:'lang-may',savedAt:new Date().toISOString(),state:s,cards:{opponents:Cards.names.slice(1),stake:cardStake,game:cardGame,stats:cardStats,recorded:cardRecorded}},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lang-may-'+F.dateKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo bản sao lưu. Giữ tệp để chuyển máy hoặc khôi phục.')}
document.addEventListener('click',e=>{if(window.farmSync?.blocked)return;const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const k=b.dataset.key,a=b.dataset.action;switch(a){case 'pondTab':pondTab=k;render();break;case 'chooseBait':if(Object.hasOwn(F.fishingBaits,k))selectedBait=k;render();break;case 'levelGoal':questTab=F.level(s)>=F.progressionStart(s)?'special':'daily';showModal('quests');break;case 'claimWeekly':action({type:a,id:k});break;case 'claimSpecial':action({type:a});break;case 'plotPage':plotPage=Number(k);render();break;case 'buyShoes':case 'equipShoes':case 'buyHat':case 'equipHat':case 'buyOutfit':case 'equipOutfit':case 'buyItem':case 'buyBundle':case 'useItem':action({type:a,key:k,crop:k,index:Number(b.dataset.index)});break;case 'shoes':case 'hats':case 'wardrobe':case 'supplies':case 'wholesale':showModal(a);break;case 'close':close();break;case 'nets':case 'pondUpgrade':case 'work':case 'seeds':case 'shop':case 'bag':case 'quests':case 'levels':case 'profile':case 'orders':case 'recipes':case 'settings':case 'help':showModal(a);break;case 'pen':{const r=b.getBoundingClientRect?.(),w=$('world').getBoundingClientRect?.();// barn: walk to the pen's gate first, then open it
if(!(s.zone==='barn'&&r&&w?.width&&window.movePlayer((r.left+r.width/2-w.left)/w.width*100,(r.bottom-w.top)/w.height*100,()=>penDialog(k))))penDialog(k);break}case 'upgradePen':action({type:a,animal:k});break;case 'startWork':action({type:a,key:k});break;case 'collectWork':action({type:a});break;case 'gender':profileGender=k;document.querySelectorAll('[data-action="gender"]').forEach(x=>x.classList.toggle('chosen',x.dataset.key===k));break;case 'questTab':questTab=k;showModal('quests');break;case 'travel':travel(k);break;case 'unlock':if(action({type:'unlock',zone:k}))close();break;case 'seed':seed=k;tool='seed';render();if(modalView==='seeds')close();break;case 'tool':tool=k;render();break;case 'plot':{const i=Number(b.dataset.index);if(action({type:'plot',index:i,tool,crop:seed})){const cols=window.matchMedia?.('(max-width:650px)').matches?(s.plots.length<=16?4:6):(s.plots.length<=16?4:s.plots.length<=36?6:8);movePlayer(5+(i%cols)/(cols-1)*82,94)}break}case 'buySeed':action({type:a,crop:k,count:Number(b.dataset.count)});break;case 'animal':case 'buyAnimal':action({type:a,animal:k});break;case 'buyPet':action({type:a,key:k});break;case 'castNet':{const i=Number(b.dataset.index);if(modalView)close();justNet=i;clearTimeout(netSpot.t);netSpot.t=setTimeout(()=>{justNet=-1},1400);window.farmAudio?.effect('water');action({type:a,kind:k,index:i});break}case 'collectNet':action({type:a,index:Number(b.dataset.index)});break;case 'haulNet':haulNet(Number(b.dataset.index));break;case 'netSpot':netSpot(Number(b.dataset.index));break;case 'upgradePond':action({type:a});break;case 'fish':{const i=Number(b.dataset.index),t=s.fishing[i];if(t&&t<=Date.now()&&window.startReel){startReel(i);break}if(!t)castAt(i);action({type:a,index:i,bait:selectedBait});break}case 'craft':action({type:a,recipe:k});break;case 'claim':action({type:a,id:k,daily:b.dataset.daily==='true'});break;case 'gift':action({type:a});break;case 'order':action({type:a,id:k});break;case 'sell':action({type:a,item:k,count:Number($('sell-'+k).value)});break;case 'sellAllConfirm':modal('Bán toàn bộ nông sản?',`<p class="modal-note">Toàn bộ nông sản và món đã chế biến sẽ được bán. Nếu đang chuẩn bị đơn hàng hoặc nguyên liệu cho xưởng, bạn có thể giữ lại.</p><button class="primary full" data-action="sellAll">Bán toàn bộ</button><button class="text-link full" data-action="bag">Quay lại kho</button>`,'confirmSell');break;case 'sellAll':if(action({type:'sell',item:'all'}))showModal('bag');break;case 'expandFarm':expand('Farm');break;case 'expandPond':expand('Pond');break;case 'confirmExpandFarm':case 'confirmExpandPond':if(action({type:a==='confirmExpandFarm'?'expandFarm':'expandPond'}))close();break;case 'export':backup();break;case 'import':$('importFile').click();break;case 'restore':if(pendingImport){s=pendingImport;pendingImport=null;if(pendingCards){Cards.setPlayers(pendingCards.opponents);cardGame=pendingCards.game||null;cardStats=pendingCards.stats||{played:0,wins:0};cardRecorded=!!pendingCards.recorded;cardStake=Cards.validStake(pendingCards.stake)&&pendingCards.stake>=5000?pendingCards.stake:5000;pendingCards=null;}else{cardGame=null;cardRecorded=false;}cardSelected=[];saveCards();loadWarning='';F.refreshDaily(s);save();render();close();toast('Đã khôi phục nông trại.');if(!s.profile.name)showModal('profile')}break;case 'acceptFresh':modal('Bắt đầu lại?',`<p class="modal-note">Dữ liệu không đọc được sẽ được thay bằng nông trại mới đang hiển thị. Bạn có thể hủy và nhập bản sao lưu trước.</p><button class="primary full" data-action="confirmFresh">Dùng nông trại mới</button><button class="text-link full" data-action="settings">Hủy</button>`,'confirmFresh');break;case 'confirmFresh':loadWarning='';save();showModal('settings');break;case 'fullscreen':(async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Trình duyệt chưa hỗ trợ toàn màn hình.')}})();break}});
$('importFile').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>1e6)throw Error('Tệp sao lưu quá lớn.');const data=JSON.parse(await file.text());if(data.game!=='lang-may'||!data.state)throw Error('Đây không phải bản sao lưu Làng Mây.');pendingImport=F.migrate(data.state);pendingCards=data.cards||null;if(pendingCards){if(pendingCards.game)Cards.validateGame(pendingCards.game);if(!Array.isArray(pendingCards.opponents)||pendingCards.opponents.length!==3||new Set(pendingCards.opponents).size!==3||pendingCards.opponents.some(n=>!Cards.playerPool.includes(n)))throw Error('Tên cùng chơi không hợp lệ.');}modal('Khôi phục nông trại?',`<p class="modal-note">Bản sao lưu của <b>${esc(pendingImport.profile.name||'Nhà nông')}</b>, cấp ${F.level(pendingImport)}, ${pendingImport.coins} xu.<br>Tiến độ hiện tại sẽ được thay bằng bản này.</p><button class="primary full" data-action="restore">Khôi phục bản này</button><button class="text-link full" data-action="settings">Hủy</button>`,'restore')}catch(err){pendingImport=null;toast('Không thể khôi phục: '+err.message)}};
$('closeModal').onclick=close;$('modal').addEventListener('cancel',e=>{if(!s.profile.name)e.preventDefault();else modalView=''});$('toggleTasks').onclick=()=>{const p=$('toggleTasks').parentElement,c=p.classList.toggle('collapsed');$('toggleTasks').setAttribute('aria-expanded',String(!c));$('taskToggleIcon').textContent=c?'+':'−'};
$('world').addEventListener('click',e=>{if(window.farmSync?.blocked||e.target.closest('button,article')||!['farm','village','barn'].includes(s.zone))return;const r=$('world').getBoundingClientRect();movePlayer((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100)});document.addEventListener('keydown',e=>{if(window.farmSync?.blocked||$('modal').open||e.target.closest('input,textarea,select,[contenteditable=true]'))return;const moves={ArrowLeft:[-4,0],a:[-4,0],ArrowRight:[4,0],d:[4,0],ArrowUp:[0,-4],w:[0,-4],ArrowDown:[0,4],s:[0,4]};if(moves[e.key]){e.preventDefault();movePlayer(s.pos.x+moves[e.key][0],s.pos.y+moves[e.key][1])}});

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_farm',description:'Read the current player, level, inventory and available farm zones.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:s.profile.name,level:F.level(s),coins:s.coins,zone:s.zone,inventory:s.bag,unlocked:s.unlocked})})).catch(()=>{})}catch{}}
if(window.matchMedia?.('(max-width:650px)').matches){$('toggleTasks').parentElement.classList.add('collapsed');$('toggleTasks').setAttribute('aria-expanded','false');$('taskToggleIcon').textContent='+'}render();if(!loadWarning)save();if(!s.profile.name)showModal('profile');else if(loadWarning)showModal('settings');setInterval(()=>{if(document.hidden)return;for(const t of s.fishing){if(t&&t<=Date.now()&&!fishAlerts.has(t)){fishAlerts.add(t);if(s.zone==='pond'){window.farmAudio?.effect('fish');toast('Cá cắn câu! Chạm phao để thu cá về kho.')}}}const old=s.daily.date;F.refreshDaily(s);if(old!==s.daily.date&&!window.farmSync?.blocked)save();const sig=signature();if(sig!==tickSignature){render();if((['recipes','quests','orders','work','nets','cookbook'].includes(modalView)||modalView.startsWith('pen:')))showModal(modalView)}document.querySelectorAll('[data-countdown]').forEach(el=>{el.textContent=clock((Number(el.dataset.countdown)-Date.now())/1000)});document.querySelectorAll('.grow-bar[data-to]').forEach(el=>{const a=Number(el.dataset.from),b=Number(el.dataset.to);el.style.setProperty('--grow',Math.round(Math.max(0,Math.min(1,(Date.now()-a)/(b-a)))*100)+'%')})},1000);

function legacyExpand(kind){if(kind==='Farm'){const u=F.landExpansion(s),extra=s.plots.length>=48;modal('Mở rộng đất · '+s.plots.length+'/96 ô',`<p class="modal-note">${extra?'Từ cấp 100, mua lẻ từng ô. Ô đầu giá 20.000 xu; mỗi ô tiếp theo tăng 2.000 xu. Mỗi cánh đồng hiển thị tối đa 48 ô.':'Mở khu vườn ban đầu từng đợt 4 ô, tối đa 48 ô. Từ cấp 100 có thể mua thêm từng ô ở cánh đồng mới.'}</p>${u?`<button class="primary full" data-action="confirmExpandFarm" ${F.level(s)<u.level||s.coins<u.cost?'disabled':''}>${extra?'Mua 1 ô đất':'Mở thêm 4 ô'} · ${u.cost.toLocaleString('vi-VN')} xu</button><p class="modal-note">Cần cấp ${u.level} · Bạn đang cấp ${F.level(s)} · Có ${s.coins.toLocaleString('vi-VN')} xu.</p>${extra?`<p>Mua xong có ${s.plots.length+1} ô. ${s.plots.length+1<96?'Ô tiếp theo: '+(u.cost+2000).toLocaleString('vi-VN')+' xu.':'Đã đạt giới hạn 96 ô.'}</p>`:''}`:'<p>Đã mở đủ 96 ô đất.</p>'}${!extra?`<div class="level-list">${Object.entries(F.landUpgrades).map(([count,u])=>`<div class="level-row ${s.plots.length>Number(count)?'achieved':''}"><b>${Number(count)+4}</b><div><strong>${Number(count)+4} ô đất</strong><small>Cấp ${u.level} · ${u.cost} xu ${s.plots.length>Number(count)?'· Đã mở':''}</small></div></div>`).join('')}</div>`:''}`,'land');return}const t=F.fishingUpgrades[s.fishing.length];if(!t)return toast('Bạn đã mở rộng tối đa.');modal('Mở rộng chỗ câu',`<div class="unlock-card"><p>Thêm 1 vị trí câu cá</p><p>Cần cấp ${t[0]} và ${t[1]} xu.</p><button class="primary full" data-action="confirmExpandPond" ${F.level(s)<t[0]||s.coins<t[1]?'disabled':''}>Mở rộng · ${t[1]} xu</button></div>`,'expand')}

